const routes = {"/":{"body":"<!doctype html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <meta name=\"theme-color\" content=\"#f6efdf\">\n  <meta name=\"description\" content=\"A messy-on-purpose sticky note board for capturing, doodling, and organizing ideas.\">\n  <title>Notesguy — make a mess, find the idea</title>\n  <link rel=\"stylesheet\" href=\"styles.css?v=20260901-2\">\n</head>\n<body>\n  <main class=\"app-shell\">\n    <aside class=\"idea-dock\" aria-label=\"Add an idea\">\n      <header class=\"brand\">\n        <span class=\"brand-mark\" aria-hidden=\"true\">✦</span>\n        <div>\n          <p class=\"eyebrow\">Avery's brain, but visible</p>\n          <h1>notes<span>guy</span></h1>\n        </div>\n      </header>\n\n      <div class=\"scribble\" aria-hidden=\"true\"></div>\n\n      <form id=\"noteForm\" class=\"note-maker\">\n        <label for=\"noteInput\">Quick—what are you thinking?</label>\n        <textarea id=\"noteInput\" maxlength=\"240\" placeholder=\"Type the half-baked idea here…\" required></textarea>\n        <div class=\"maker-row\">\n          <div class=\"swatches\" aria-label=\"Choose note color\">\n            <button class=\"swatch is-selected\" type=\"button\" data-color=\"yellow\" aria-label=\"Yellow note\"></button>\n            <button class=\"swatch\" type=\"button\" data-color=\"pink\" aria-label=\"Pink note\"></button>\n            <button class=\"swatch\" type=\"button\" data-color=\"blue\" aria-label=\"Blue note\"></button>\n          </div>\n          <button class=\"add-note\" type=\"submit\">stick it! <span aria-hidden=\"true\">↗</span></button>\n        </div>\n      </form>\n\n      <p class=\"tiny-note\">No logins. No judgment. Saved on this device.</p>\n    </aside>\n\n    <section class=\"board-wrap\" aria-label=\"Brainstorm board\">\n      <div class=\"board-heading\">\n        <div>\n          <p class=\"kicker\">TODAY'S BIG MESS</p>\n          <h2>Make a mess. <em>Find the idea.</em></h2>\n        </div>\n        <div class=\"heading-actions\">\n          <div class=\"live-count\"><strong id=\"noteCount\">0</strong><span>ideas<br>in motion</span></div>\n          <button id=\"savedBtn\" class=\"saved-tab\" type=\"button\" aria-expanded=\"false\" aria-controls=\"savedDrawer\">\n            <span aria-hidden=\"true\">⌑</span> Saved <strong id=\"savedCount\">0</strong>\n          </button>\n        </div>\n      </div>\n\n      <div id=\"board\" class=\"board\">\n        <div id=\"groupsLayer\" class=\"groups-layer\"></div>\n        <canvas id=\"doodleCanvas\" aria-label=\"Doodle layer\"></canvas>\n        <div id=\"itemsLayer\" class=\"items-layer\"></div>\n        <div id=\"emptyState\" class=\"empty-state\" hidden>\n          <span aria-hidden=\"true\">↖</span>\n          <p>Your brilliant mess<br>starts over there.</p>\n        </div>\n        <div id=\"selectionDock\" class=\"selection-dock\" hidden>\n          <div class=\"selection-copy\">\n            <strong id=\"selectionTitle\">Pick notes</strong>\n            <span><b id=\"selectionCount\">0</b> selected</span>\n          </div>\n          <div id=\"batchTools\" class=\"batch-tools\">\n            <button class=\"mini-swatch yellow\" type=\"button\" data-batch-color=\"yellow\" aria-label=\"Make selected notes yellow\"></button>\n            <button class=\"mini-swatch pink\" type=\"button\" data-batch-color=\"pink\" aria-label=\"Make selected notes pink\"></button>\n            <button class=\"mini-swatch blue\" type=\"button\" data-batch-color=\"blue\" aria-label=\"Make selected notes blue\"></button>\n            <label class=\"tag-field\"><span>#</span><input id=\"tagInput\" maxlength=\"18\" placeholder=\"add tag\" aria-label=\"Tag selected notes\"></label>\n            <button id=\"tagBtn\" class=\"dock-action\" type=\"button\">Tag</button>\n            <button id=\"groupBtn\" class=\"dock-action strong\" type=\"button\">Group</button>\n          </div>\n          <button id=\"archiveSelectedBtn\" class=\"dock-action strong\" type=\"button\" hidden>Save selected</button>\n          <button id=\"cancelSelectionBtn\" class=\"dock-close\" type=\"button\" aria-label=\"Cancel selection\">×</button>\n        </div>\n      </div>\n\n      <nav class=\"toolbelt\" aria-label=\"Brainstorm tools\">\n        <button id=\"doodleBtn\" class=\"tool\" type=\"button\" aria-pressed=\"false\"><span class=\"tool-icon doodle-icon\" aria-hidden=\"true\"></span>Doodle</button>\n        <button id=\"eraserBtn\" class=\"tool\" type=\"button\" aria-pressed=\"false\"><span class=\"tool-icon\" aria-hidden=\"true\">▱</span>Eraser</button>\n        <button id=\"saveBtn\" class=\"tool\" type=\"button\" aria-pressed=\"false\"><span class=\"tool-icon\" aria-hidden=\"true\">⌑</span>Save</button>\n        <button id=\"selectBtn\" class=\"tool\" type=\"button\" aria-pressed=\"false\"><span class=\"tool-icon\" aria-hidden=\"true\">☑</span>Select</button>\n        <button id=\"arrowBtn\" class=\"tool\" type=\"button\"><span class=\"tool-icon\" aria-hidden=\"true\">↗</span>Add arrow</button>\n        <button id=\"tidyBtn\" class=\"tool\" type=\"button\"><span class=\"tool-icon\" aria-hidden=\"true\">▦</span>Tidy up</button>\n        <button id=\"undoBtn\" class=\"tool\" type=\"button\"><span class=\"tool-icon\" aria-hidden=\"true\">↶</span>Undo</button>\n        <button id=\"clearBtn\" class=\"tool danger\" type=\"button\"><span class=\"tool-icon\" aria-hidden=\"true\">×</span>Clear</button>\n      </nav>\n\n      <aside id=\"savedDrawer\" class=\"saved-drawer\" aria-label=\"Saved notes\" hidden>\n        <header>\n          <div><p>THE KEEP PILE</p><h3>Saved notes</h3></div>\n          <button id=\"closeSavedBtn\" type=\"button\" aria-label=\"Close saved notes\">×</button>\n        </header>\n        <p class=\"drawer-help\">Old thoughts, safely tucked away. Restore one whenever it becomes useful again.</p>\n        <div id=\"savedList\" class=\"saved-list\"></div>\n      </aside>\n\n      <div id=\"modeHint\" class=\"mode-hint\" role=\"status\" aria-live=\"polite\">Drag notes anywhere. Double-click one to edit.</div>\n    </section>\n  </main>\n  <script src=\"script.js?v=20260901-2\"></script>\n</body>\n</html>\n","type":"text/html; charset=utf-8"},"/index.html":{"body":"<!doctype html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <meta name=\"theme-color\" content=\"#f6efdf\">\n  <meta name=\"description\" content=\"A messy-on-purpose sticky note board for capturing, doodling, and organizing ideas.\">\n  <title>Notesguy — make a mess, find the idea</title>\n  <link rel=\"stylesheet\" href=\"styles.css?v=20260901-2\">\n</head>\n<body>\n  <main class=\"app-shell\">\n    <aside class=\"idea-dock\" aria-label=\"Add an idea\">\n      <header class=\"brand\">\n        <span class=\"brand-mark\" aria-hidden=\"true\">✦</span>\n        <div>\n          <p class=\"eyebrow\">Avery's brain, but visible</p>\n          <h1>notes<span>guy</span></h1>\n        </div>\n      </header>\n\n      <div class=\"scribble\" aria-hidden=\"true\"></div>\n\n      <form id=\"noteForm\" class=\"note-maker\">\n        <label for=\"noteInput\">Quick—what are you thinking?</label>\n        <textarea id=\"noteInput\" maxlength=\"240\" placeholder=\"Type the half-baked idea here…\" required></textarea>\n        <div class=\"maker-row\">\n          <div class=\"swatches\" aria-label=\"Choose note color\">\n            <button class=\"swatch is-selected\" type=\"button\" data-color=\"yellow\" aria-label=\"Yellow note\"></button>\n            <button class=\"swatch\" type=\"button\" data-color=\"pink\" aria-label=\"Pink note\"></button>\n            <button class=\"swatch\" type=\"button\" data-color=\"blue\" aria-label=\"Blue note\"></button>\n          </div>\n          <button class=\"add-note\" type=\"submit\">stick it! <span aria-hidden=\"true\">↗</span></button>\n        </div>\n      </form>\n\n      <p class=\"tiny-note\">No logins. No judgment. Saved on this device.</p>\n    </aside>\n\n    <section class=\"board-wrap\" aria-label=\"Brainstorm board\">\n      <div class=\"board-heading\">\n        <div>\n          <p class=\"kicker\">TODAY'S BIG MESS</p>\n          <h2>Make a mess. <em>Find the idea.</em></h2>\n        </div>\n        <div class=\"heading-actions\">\n          <div class=\"live-count\"><strong id=\"noteCount\">0</strong><span>ideas<br>in motion</span></div>\n          <button id=\"savedBtn\" class=\"saved-tab\" type=\"button\" aria-expanded=\"false\" aria-controls=\"savedDrawer\">\n            <span aria-hidden=\"true\">⌑</span> Saved <strong id=\"savedCount\">0</strong>\n          </button>\n        </div>\n      </div>\n\n      <div id=\"board\" class=\"board\">\n        <div id=\"groupsLayer\" class=\"groups-layer\"></div>\n        <canvas id=\"doodleCanvas\" aria-label=\"Doodle layer\"></canvas>\n        <div id=\"itemsLayer\" class=\"items-layer\"></div>\n        <div id=\"emptyState\" class=\"empty-state\" hidden>\n          <span aria-hidden=\"true\">↖</span>\n          <p>Your brilliant mess<br>starts over there.</p>\n        </div>\n        <div id=\"selectionDock\" class=\"selection-dock\" hidden>\n          <div class=\"selection-copy\">\n            <strong id=\"selectionTitle\">Pick notes</strong>\n            <span><b id=\"selectionCount\">0</b> selected</span>\n          </div>\n          <div id=\"batchTools\" class=\"batch-tools\">\n            <button class=\"mini-swatch yellow\" type=\"button\" data-batch-color=\"yellow\" aria-label=\"Make selected notes yellow\"></button>\n            <button class=\"mini-swatch pink\" type=\"button\" data-batch-color=\"pink\" aria-label=\"Make selected notes pink\"></button>\n            <button class=\"mini-swatch blue\" type=\"button\" data-batch-color=\"blue\" aria-label=\"Make selected notes blue\"></button>\n            <label class=\"tag-field\"><span>#</span><input id=\"tagInput\" maxlength=\"18\" placeholder=\"add tag\" aria-label=\"Tag selected notes\"></label>\n            <button id=\"tagBtn\" class=\"dock-action\" type=\"button\">Tag</button>\n            <button id=\"groupBtn\" class=\"dock-action strong\" type=\"button\">Group</button>\n          </div>\n          <button id=\"archiveSelectedBtn\" class=\"dock-action strong\" type=\"button\" hidden>Save selected</button>\n          <button id=\"cancelSelectionBtn\" class=\"dock-close\" type=\"button\" aria-label=\"Cancel selection\">×</button>\n        </div>\n      </div>\n\n      <nav class=\"toolbelt\" aria-label=\"Brainstorm tools\">\n        <button id=\"doodleBtn\" class=\"tool\" type=\"button\" aria-pressed=\"false\"><span class=\"tool-icon doodle-icon\" aria-hidden=\"true\"></span>Doodle</button>\n        <button id=\"eraserBtn\" class=\"tool\" type=\"button\" aria-pressed=\"false\"><span class=\"tool-icon\" aria-hidden=\"true\">▱</span>Eraser</button>\n        <button id=\"saveBtn\" class=\"tool\" type=\"button\" aria-pressed=\"false\"><span class=\"tool-icon\" aria-hidden=\"true\">⌑</span>Save</button>\n        <button id=\"selectBtn\" class=\"tool\" type=\"button\" aria-pressed=\"false\"><span class=\"tool-icon\" aria-hidden=\"true\">☑</span>Select</button>\n        <button id=\"arrowBtn\" class=\"tool\" type=\"button\"><span class=\"tool-icon\" aria-hidden=\"true\">↗</span>Add arrow</button>\n        <button id=\"tidyBtn\" class=\"tool\" type=\"button\"><span class=\"tool-icon\" aria-hidden=\"true\">▦</span>Tidy up</button>\n        <button id=\"undoBtn\" class=\"tool\" type=\"button\"><span class=\"tool-icon\" aria-hidden=\"true\">↶</span>Undo</button>\n        <button id=\"clearBtn\" class=\"tool danger\" type=\"button\"><span class=\"tool-icon\" aria-hidden=\"true\">×</span>Clear</button>\n      </nav>\n\n      <aside id=\"savedDrawer\" class=\"saved-drawer\" aria-label=\"Saved notes\" hidden>\n        <header>\n          <div><p>THE KEEP PILE</p><h3>Saved notes</h3></div>\n          <button id=\"closeSavedBtn\" type=\"button\" aria-label=\"Close saved notes\">×</button>\n        </header>\n        <p class=\"drawer-help\">Old thoughts, safely tucked away. Restore one whenever it becomes useful again.</p>\n        <div id=\"savedList\" class=\"saved-list\"></div>\n      </aside>\n\n      <div id=\"modeHint\" class=\"mode-hint\" role=\"status\" aria-live=\"polite\">Drag notes anywhere. Double-click one to edit.</div>\n    </section>\n  </main>\n  <script src=\"script.js?v=20260901-2\"></script>\n</body>\n</html>\n","type":"text/html; charset=utf-8"},"/styles.css":{"body":":root {\n  --ink: #202020;\n  --paper: #f4ecdd;\n  --board: #fbf8ef;\n  --red: #f05a49;\n  --yellow: #f8df66;\n  --pink: #f4a6b9;\n  --blue: #9ed8e8;\n  --shadow: 5px 7px 0 rgba(32, 32, 32, .14);\n}\n\n* { box-sizing: border-box; }\n\nhtml, body { margin: 0; height: 100%; overflow: hidden; }\n\nbody {\n  color: var(--ink);\n  background: var(--paper);\n  font-family: Arial, Helvetica, sans-serif;\n}\n\nbutton, textarea { font: inherit; }\nbutton { color: inherit; }\n\n.app-shell {\n  display: grid;\n  grid-template-columns: minmax(260px, 22vw) 1fr;\n  height: 100dvh;\n  padding: 14px;\n  gap: 14px;\n}\n\n.idea-dock {\n  position: relative;\n  display: flex;\n  flex-direction: column;\n  min-height: 0;\n  padding: clamp(18px, 2.4vw, 34px);\n  border: 2px solid var(--ink);\n  border-radius: 8px 24px 8px 8px;\n  background: #f7f0df;\n  overflow: hidden;\n}\n\n.idea-dock::before {\n  content: \"\";\n  position: absolute;\n  width: 105px;\n  height: 24px;\n  top: -8px;\n  left: 50%;\n  transform: translateX(-50%) rotate(-2deg);\n  background: rgba(255,255,255,.48);\n  border: 1px solid rgba(32,32,32,.12);\n}\n\n.brand { display: flex; align-items: center; gap: 10px; }\n.brand-mark {\n  display: grid;\n  width: 36px;\n  height: 36px;\n  place-items: center;\n  border-radius: 50%;\n  background: var(--red);\n  font-size: 22px;\n  transform: rotate(-9deg);\n}\n.eyebrow, .kicker {\n  margin: 0 0 2px;\n  font-size: 10px;\n  font-weight: 900;\n  letter-spacing: .14em;\n  text-transform: uppercase;\n}\n.brand h1 {\n  margin: 0;\n  font: 900 clamp(25px, 3vw, 40px)/.88 Georgia, serif;\n  letter-spacing: -.06em;\n}\n.brand h1 span { color: var(--red); font-style: italic; }\n\n.scribble {\n  width: 86%;\n  height: 28px;\n  margin: clamp(20px, 4vh, 52px) auto 8px;\n  border-top: 3px solid var(--ink);\n  border-radius: 50%;\n  transform: rotate(-2deg);\n  opacity: .8;\n}\n.scribble::after {\n  content: \"\";\n  display: block;\n  width: 70%;\n  height: 18px;\n  margin: -12px auto 0;\n  border-bottom: 2px solid var(--red);\n  border-radius: 50%;\n  transform: rotate(4deg);\n}\n\n.note-maker { margin-top: auto; margin-bottom: auto; }\n.note-maker label {\n  display: block;\n  margin-bottom: 12px;\n  font: 700 clamp(17px, 1.5vw, 23px)/1.05 \"Comic Sans MS\", \"Segoe Print\", cursive;\n  transform: rotate(-1deg);\n}\n.note-maker textarea {\n  width: 100%;\n  height: clamp(120px, 24vh, 210px);\n  padding: 18px;\n  resize: none;\n  color: var(--ink);\n  border: 2px solid var(--ink);\n  border-radius: 3px;\n  outline: none;\n  background: var(--yellow);\n  box-shadow: var(--shadow);\n  font: 600 16px/1.4 \"Comic Sans MS\", \"Segoe Print\", cursive;\n  transform: rotate(-.6deg);\n  transition: transform .2s, box-shadow .2s, background .2s;\n}\n.note-maker textarea:focus { transform: rotate(0) translateY(-2px); box-shadow: 7px 9px 0 rgba(32,32,32,.18); }\n.note-maker textarea::placeholder { color: rgba(32,32,32,.53); }\n.maker-row { display: flex; align-items: center; justify-content: space-between; gap: 10px; margin-top: 15px; }\n.swatches { display: flex; gap: 7px; }\n.swatch {\n  width: 22px;\n  height: 22px;\n  padding: 0;\n  border: 1px solid var(--ink);\n  border-radius: 50%;\n  cursor: pointer;\n}\n.swatch[data-color=\"yellow\"] { background: var(--yellow); }\n.swatch[data-color=\"pink\"] { background: var(--pink); }\n.swatch[data-color=\"blue\"] { background: var(--blue); }\n.swatch.is-selected { outline: 2px solid var(--ink); outline-offset: 3px; }\n.add-note {\n  padding: 11px 17px;\n  border: 2px solid var(--ink);\n  border-radius: 999px;\n  background: var(--red);\n  box-shadow: 3px 3px 0 var(--ink);\n  font-weight: 900;\n  cursor: pointer;\n  transition: transform .12s, box-shadow .12s;\n}\n.add-note:hover { transform: translate(-1px,-1px) rotate(-1deg); box-shadow: 5px 5px 0 var(--ink); }\n.add-note:active { transform: translate(2px,2px); box-shadow: 1px 1px 0 var(--ink); }\n.tiny-note { margin: 0; font-size: 10px; font-weight: 700; opacity: .58; text-align: center; }\n\n.board-wrap {\n  position: relative;\n  display: grid;\n  grid-template-rows: auto minmax(0, 1fr) auto;\n  min-width: 0;\n  min-height: 0;\n  padding: clamp(16px, 2.2vw, 30px) clamp(16px, 2.6vw, 38px) 18px;\n  border: 2px solid var(--ink);\n  border-radius: 22px 7px 22px 7px;\n  background-color: var(--board);\n  background-image: radial-gradient(rgba(32,32,32,.105) .75px, transparent .75px);\n  background-size: 15px 15px;\n  overflow: hidden;\n}\n.board-heading { display: flex; align-items: flex-start; justify-content: space-between; gap: 20px; z-index: 5; }\n.kicker { color: var(--red); }\n.board-heading h2 {\n  margin: 2px 0 10px;\n  font: 900 clamp(22px, 3vw, 46px)/1 Georgia, serif;\n  letter-spacing: -.055em;\n}\n.board-heading h2 em { font-family: \"Comic Sans MS\", \"Segoe Print\", cursive; font-weight: 400; }\n.live-count { display: flex; align-items: center; gap: 7px; padding-top: 2px; transform: rotate(3deg); }\n.live-count strong { font: 900 32px/1 Georgia, serif; color: var(--red); }\n.live-count span { font-size: 9px; line-height: 1.05; font-weight: 900; text-transform: uppercase; }\n.heading-actions { display: flex; align-items: center; gap: 12px; }\n.saved-tab {\n  display: flex;\n  align-items: center;\n  gap: 7px;\n  padding: 9px 13px;\n  border: 2px solid var(--ink);\n  border-radius: 7px 14px 7px 12px;\n  background: var(--yellow);\n  box-shadow: 3px 3px 0 var(--ink);\n  font-size: 12px;\n  font-weight: 900;\n  cursor: pointer;\n  transform: rotate(1deg);\n}\n.saved-tab:hover, .saved-tab[aria-expanded=\"true\"] { background: #fff; transform: rotate(0) translateY(-1px); }\n.saved-tab strong { display: grid; min-width: 20px; height: 20px; place-items: center; border-radius: 50%; color: #fff; background: var(--red); font-size: 10px; }\n\n.board { position: relative; min-height: 0; overflow: hidden; touch-action: none; }\n.board::before {\n  content: \"\";\n  position: absolute;\n  inset: 8px 0 13px;\n  border: 1.5px dashed rgba(32,32,32,.16);\n  border-radius: 45% 55% 48% 52% / 3% 4% 3% 4%;\n  pointer-events: none;\n}\n.items-layer, .groups-layer, #doodleCanvas { position: absolute; inset: 0; width: 100%; height: 100%; }\n.groups-layer { z-index: 1; pointer-events: none; }\n.items-layer { z-index: 2; pointer-events: none; }\n#doodleCanvas { z-index: 3; pointer-events: none; }\n#doodleCanvas.is-active { pointer-events: auto; cursor: crosshair; }\n#doodleCanvas.is-erasing { cursor: cell; }\n\n.group-box {\n  position: absolute;\n  min-width: 160px;\n  min-height: 145px;\n  border: 2px dashed color-mix(in srgb, var(--group-color, #202020) 70%, transparent);\n  border-radius: 17px 8px 21px 9px;\n  background: color-mix(in srgb, var(--group-color, #f8df66) 10%, transparent);\n}\n.group-label {\n  position: absolute;\n  top: -13px;\n  left: 16px;\n  padding: 4px 10px;\n  border: 1.5px solid var(--ink);\n  border-radius: 999px;\n  background: var(--board);\n  font: 900 10px/1 \"Comic Sans MS\", cursive;\n  text-transform: uppercase;\n  letter-spacing: .06em;\n}\n\n.sticky {\n  position: absolute;\n  display: flex;\n  width: clamp(132px, 15vw, 190px);\n  aspect-ratio: 1.08;\n  padding: 24px 18px 16px;\n  border: 1.5px solid var(--ink);\n  background: var(--yellow);\n  box-shadow: var(--shadow);\n  transform: rotate(var(--tilt, -2deg));\n  pointer-events: auto;\n  cursor: grab;\n  user-select: none;\n  transition: box-shadow .15s;\n}\n.sticky[data-color=\"pink\"] { background: var(--pink); }\n.sticky[data-color=\"blue\"] { background: var(--blue); }\n.sticky::before {\n  content: \"\";\n  position: absolute;\n  top: -7px;\n  left: 50%;\n  width: 58px;\n  height: 17px;\n  background: rgba(255,255,255,.53);\n  border: 1px solid rgba(32,32,32,.12);\n  transform: translateX(-50%) rotate(1deg);\n}\n.sticky.is-dragging { cursor: grabbing; box-shadow: 10px 13px 0 rgba(32,32,32,.15); z-index: 20; }\n.sticky.is-selected { outline: 4px solid var(--red); outline-offset: 5px; z-index: 12; }\n.sticky.is-selected::after {\n  content: \"✓\";\n  position: absolute;\n  top: -15px;\n  right: -14px;\n  display: grid;\n  width: 27px;\n  height: 27px;\n  place-items: center;\n  border: 2px solid var(--ink);\n  border-radius: 50%;\n  color: #fff;\n  background: var(--red);\n  font: 900 14px/1 Arial, sans-serif;\n}\n.sticky-text {\n  position: relative;\n  z-index: 2;\n  width: 100%;\n  overflow: hidden;\n  outline: none;\n  font: 700 clamp(13px, 1.4vw, 18px)/1.28 \"Comic Sans MS\", \"Segoe Print\", cursive;\n  white-space: pre-wrap;\n}\n.sticky-text[contenteditable=\"true\"] { cursor: text; user-select: text; background: rgba(255,255,255,.2); }\n.note-tag {\n  position: absolute;\n  z-index: 3;\n  left: 12px;\n  bottom: 7px;\n  max-width: calc(100% - 24px);\n  padding: 3px 7px;\n  overflow: hidden;\n  border: 1px solid rgba(32,32,32,.45);\n  border-radius: 999px;\n  background: rgba(255,255,255,.45);\n  font: 900 9px/1 Arial, sans-serif;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n.note-ink {\n  position: absolute;\n  z-index: 3;\n  inset: 0;\n  width: 100%;\n  height: 100%;\n  pointer-events: none;\n}\n.note-ink.is-active { pointer-events: auto; cursor: crosshair; }\n.note-toolbar {\n  position: absolute;\n  z-index: 80;\n  top: calc(100% + 8px);\n  left: 50%;\n  display: flex;\n  align-items: center;\n  gap: 4px;\n  width: max-content;\n  max-width: 230px;\n  padding: 6px;\n  border: 2px solid var(--ink);\n  border-radius: 999px;\n  background: #fffdf7;\n  box-shadow: 4px 5px 0 rgba(32,32,32,.2);\n  transform: translateX(-50%) rotate(calc(var(--tilt, 0deg) * -1));\n}\n.sticky.toolbar-above .note-toolbar { top: auto; bottom: calc(100% + 8px); }\n.note-toolbar button {\n  min-height: 28px;\n  padding: 4px 8px;\n  border: 1px solid var(--ink);\n  border-radius: 999px;\n  background: #fff;\n  font-size: 10px;\n  font-weight: 900;\n  cursor: pointer;\n}\n.note-toolbar button:hover, .note-toolbar button.is-active { color: #fff; background: var(--ink); }\n.note-toolbar .toolbar-color { width: 24px; min-height: 24px; padding: 0; font-size: 0; }\n.note-toolbar .toolbar-color.yellow { background: var(--yellow); }\n.note-toolbar .toolbar-color.pink { background: var(--pink); }\n.note-toolbar .toolbar-color.blue { background: var(--blue); }\n.delete-note {\n  position: absolute;\n  top: 5px;\n  right: 6px;\n  width: 22px;\n  height: 22px;\n  padding: 0;\n  border: 0;\n  background: transparent;\n  font-size: 19px;\n  font-weight: 900;\n  cursor: pointer;\n  opacity: 0;\n}\n.sticky:hover .delete-note, .sticky:focus-within .delete-note { opacity: .55; }\n\n.arrow-sticker {\n  position: absolute;\n  z-index: 1;\n  border: 0;\n  background: transparent;\n  color: var(--red);\n  font: 900 clamp(50px, 7vw, 90px)/1 \"Comic Sans MS\", cursive;\n  transform: rotate(var(--turn, -20deg));\n  text-shadow: 1px 1px 0 var(--ink);\n  pointer-events: auto;\n  cursor: grab;\n}\n\n.empty-state { position: absolute; inset: 22% auto auto 7%; color: rgba(32,32,32,.45); transform: rotate(-7deg); }\n.empty-state span { font: 700 55px/1 \"Comic Sans MS\", cursive; }\n.empty-state p { margin: -5px 0 0 44px; font: 700 17px/1.2 \"Comic Sans MS\", cursive; }\n\n.toolbelt {\n  z-index: 5;\n  display: flex;\n  justify-content: center;\n  gap: 5px;\n  padding-top: 8px;\n}\n.tool {\n  display: flex;\n  align-items: center;\n  gap: 7px;\n  min-height: 39px;\n  padding: 7px 10px;\n  border: 1.5px solid var(--ink);\n  border-radius: 999px;\n  background: rgba(255,255,255,.73);\n  font-size: 10px;\n  font-weight: 900;\n  cursor: pointer;\n  box-shadow: 2px 2px 0 rgba(32,32,32,.18);\n}\n.tool:hover { background: white; transform: translateY(-2px) rotate(-1deg); }\n.tool[aria-pressed=\"true\"] { color: #fff; background: var(--ink); }\n.tool:disabled { opacity: .35; cursor: not-allowed; transform: none; }\n.tool-icon { display: grid; width: 20px; height: 20px; place-items: center; font-size: 20px; line-height: 1; }\n.doodle-icon { border-bottom: 2px wavy currentColor; transform: rotate(-8deg); }\n.danger { color: #a33427; }\n.mode-hint {\n  position: absolute;\n  right: 12px;\n  bottom: 7px;\n  font: 700 9px/1 \"Comic Sans MS\", cursive;\n  opacity: .52;\n  transform: rotate(-2deg);\n}\n\n.selection-dock {\n  position: absolute;\n  z-index: 50;\n  left: 50%;\n  bottom: 12px;\n  display: flex;\n  align-items: center;\n  gap: 9px;\n  width: min(720px, calc(100% - 18px));\n  padding: 9px 42px 9px 12px;\n  border: 2px solid var(--ink);\n  border-radius: 12px 19px 10px 17px;\n  background: #fffdf7;\n  box-shadow: 5px 6px 0 rgba(32,32,32,.18);\n  transform: translateX(-50%);\n}\n.selection-dock[hidden] { display: none; }\n.selection-copy { display: flex; flex-direction: column; min-width: 84px; }\n.selection-copy strong { font: 900 12px/1.05 \"Comic Sans MS\", cursive; }\n.selection-copy span { margin-top: 2px; font-size: 9px; font-weight: 800; opacity: .6; }\n.batch-tools { display: flex; align-items: center; gap: 5px; min-width: 0; }\n.batch-tools[hidden] { display: none; }\n.mini-swatch { width: 23px; height: 23px; padding: 0; flex: 0 0 auto; border: 1.5px solid var(--ink); border-radius: 50%; cursor: pointer; }\n.mini-swatch.yellow { background: var(--yellow); }\n.mini-swatch.pink { background: var(--pink); }\n.mini-swatch.blue { background: var(--blue); }\n.tag-field { display: flex; align-items: center; min-width: 90px; max-width: 140px; height: 29px; padding: 0 8px; border: 1.5px solid var(--ink); border-radius: 999px; background: #fff; font-weight: 900; }\n.tag-field input { width: 100%; min-width: 0; border: 0; outline: 0; background: transparent; font-size: 10px; font-weight: 800; }\n.dock-action { min-height: 29px; padding: 5px 10px; border: 1.5px solid var(--ink); border-radius: 999px; background: #fff; font-size: 10px; font-weight: 900; cursor: pointer; white-space: nowrap; }\n.dock-action.strong { color: #fff; background: var(--ink); }\n.dock-action:disabled { opacity: .35; cursor: not-allowed; }\n.dock-close { position: absolute; top: 50%; right: 10px; width: 25px; height: 25px; padding: 0; border: 0; background: transparent; font-size: 22px; font-weight: 900; cursor: pointer; transform: translateY(-50%); }\n\n.saved-drawer {\n  position: absolute;\n  z-index: 100;\n  top: 78px;\n  right: 13px;\n  bottom: 68px;\n  display: grid;\n  grid-template-rows: auto auto minmax(0, 1fr);\n  width: min(340px, calc(100% - 26px));\n  padding: 18px;\n  border: 2px solid var(--ink);\n  border-radius: 10px 22px 9px 18px;\n  background: #f7f0df;\n  box-shadow: 9px 10px 0 rgba(32,32,32,.18);\n}\n.saved-drawer[hidden] { display: none; }\n.saved-drawer header { display: flex; align-items: flex-start; justify-content: space-between; }\n.saved-drawer header p { margin: 0 0 2px; color: var(--red); font-size: 9px; font-weight: 900; letter-spacing: .14em; }\n.saved-drawer h3 { margin: 0; font: 900 28px/1 Georgia, serif; letter-spacing: -.04em; }\n.saved-drawer header button { width: 31px; height: 31px; padding: 0; border: 1.5px solid var(--ink); border-radius: 50%; background: #fff; font-size: 22px; cursor: pointer; }\n.drawer-help { margin: 10px 0 12px; font: 700 11px/1.3 \"Comic Sans MS\", cursive; opacity: .65; }\n.saved-list { min-height: 0; padding: 4px 5px 10px 2px; overflow-y: auto; scrollbar-width: thin; }\n.saved-empty { padding: 35px 10px; text-align: center; font: 700 15px/1.3 \"Comic Sans MS\", cursive; opacity: .5; }\n.saved-card { position: relative; margin: 0 0 11px; padding: 14px; border: 1.5px solid var(--ink); background: var(--yellow); box-shadow: 3px 4px 0 rgba(32,32,32,.14); transform: rotate(var(--saved-tilt, -1deg)); }\n.saved-card[data-color=\"pink\"] { background: var(--pink); }\n.saved-card[data-color=\"blue\"] { background: var(--blue); }\n.saved-card p { max-height: 55px; margin: 0 0 11px; overflow: hidden; font: 700 13px/1.25 \"Comic Sans MS\", cursive; }\n.saved-card footer { display: flex; align-items: center; justify-content: space-between; gap: 8px; }\n.saved-card small { font-size: 8px; font-weight: 900; opacity: .55; }\n.saved-card button { padding: 5px 9px; border: 1.5px solid var(--ink); border-radius: 999px; background: rgba(255,255,255,.7); font-size: 9px; font-weight: 900; cursor: pointer; }\n.saved-card .discard-saved { border: 0; background: transparent; font-size: 16px; opacity: .55; }\n\n@media (max-width: 760px) {\n  .app-shell { grid-template-columns: 1fr; grid-template-rows: 190px minmax(0, 1fr); padding: 8px; gap: 8px; }\n  .idea-dock { padding: 13px 16px; display: grid; grid-template-columns: 1fr 1.65fr; grid-template-rows: auto 1fr; gap: 8px 14px; }\n  .brand { align-self: start; }\n  .eyebrow { display: none; }\n  .brand h1 { font-size: 26px; }\n  .brand-mark { width: 29px; height: 29px; font-size: 17px; }\n  .scribble, .tiny-note { display: none; }\n  .note-maker { grid-column: 1 / -1; display: grid; grid-template-columns: 1fr auto; grid-template-rows: auto 1fr; gap: 5px 9px; margin: 0; }\n  .note-maker label { grid-column: 1 / -1; margin: 0; font-size: 14px; }\n  .note-maker textarea { height: 87px; padding: 12px; }\n  .maker-row { flex-direction: column; justify-content: flex-end; margin: 0; }\n  .add-note { padding: 8px 12px; }\n  .swatch { width: 17px; height: 17px; }\n  .board-wrap { padding: 12px 10px 10px; }\n  .board-heading h2 { font-size: clamp(20px, 6vw, 30px); margin-bottom: 4px; }\n  .live-count { display: none; }\n  .saved-tab { padding: 7px 9px; font-size: 10px; }\n  .toolbelt { gap: 4px; }\n  .tool { min-width: 40px; padding: 7px 9px; font-size: 0; justify-content: center; }\n  .tool-icon { font-size: 20px; }\n  .sticky { width: clamp(112px, 32vw, 145px); padding: 20px 12px 12px; }\n  .sticky-text { font-size: 13px; }\n  .mode-hint { display: none; }\n  .selection-dock { bottom: 7px; gap: 6px; padding: 7px 36px 7px 8px; }\n  .selection-copy { min-width: 62px; }\n  .selection-copy strong { font-size: 9px; }\n  .tag-field { width: 80px; }\n  .dock-action { padding-inline: 8px; font-size: 9px; }\n  .saved-drawer { top: 57px; bottom: 56px; }\n  .note-toolbar { max-width: 210px; gap: 3px; }\n  .note-toolbar button { padding-inline: 6px; font-size: 9px; }\n}\n\n@media (max-width: 460px) {\n  .toolbelt { gap: 2px; }\n  .tool { min-width: 33px; padding-inline: 4px; }\n  .batch-tools .mini-swatch { width: 20px; height: 20px; }\n  .tag-field { display: none; }\n  #tagBtn { display: none; }\n  .selection-copy span { display: none; }\n}\n\n@media (max-height: 620px) and (min-width: 761px) {\n  .app-shell { padding: 8px; gap: 8px; }\n  .idea-dock { padding: 14px 20px; }\n  .scribble { margin: 10px auto 2px; }\n  .note-maker label { font-size: 15px; margin-bottom: 7px; }\n  .note-maker textarea { height: 112px; padding: 12px; }\n  .tiny-note { display: none; }\n  .board-wrap { padding-top: 13px; }\n  .board-heading h2 { font-size: 28px; margin-bottom: 3px; }\n  .tool { min-height: 34px; padding-block: 5px; }\n}\n\n@media (prefers-reduced-motion: reduce) {\n  *, *::before, *::after { scroll-behavior: auto !important; transition: none !important; }\n}\n","type":"text/css; charset=utf-8"},"/script.js":{"body":"(() => {\n  const $ = selector => document.querySelector(selector);\n  const board = $('#board');\n  const layer = $('#itemsLayer');\n  const groupsLayer = $('#groupsLayer');\n  const canvas = $('#doodleCanvas');\n  const ctx = canvas.getContext('2d');\n  const form = $('#noteForm');\n  const input = $('#noteInput');\n  const count = $('#noteCount');\n  const savedCount = $('#savedCount');\n  const empty = $('#emptyState');\n  const doodleBtn = $('#doodleBtn');\n  const eraserBtn = $('#eraserBtn');\n  const saveBtn = $('#saveBtn');\n  const selectBtn = $('#selectBtn');\n  const arrowBtn = $('#arrowBtn');\n  const tidyBtn = $('#tidyBtn');\n  const undoBtn = $('#undoBtn');\n  const clearBtn = $('#clearBtn');\n  const hint = $('#modeHint');\n  const savedBtn = $('#savedBtn');\n  const savedDrawer = $('#savedDrawer');\n  const savedList = $('#savedList');\n  const selectionDock = $('#selectionDock');\n  const selectionTitle = $('#selectionTitle');\n  const selectionCount = $('#selectionCount');\n  const batchTools = $('#batchTools');\n  const archiveSelectedBtn = $('#archiveSelectedBtn');\n  const tagInput = $('#tagInput');\n\n  const STORAGE_KEY = 'notesguy-board-v2';\n  const LEGACY_KEY = 'notesguy-board-v1';\n  const colors = { yellow: '#f8df66', pink: '#f4a6b9', blue: '#9ed8e8' };\n  let selectedColor = 'yellow';\n  let state = { notes: [], arrows: [], groups: [], saved: [], doodle: '', updatedAt: 0 };\n  let history = [];\n  let selected = new Set();\n  let selectionMode = null;\n  let activeNoteId = null;\n  let noteDoodleId = null;\n  let canvasMode = null;\n  let drawing = false;\n  let noteDrawing = null;\n  let clearArmed = false;\n  let drag = null;\n  let suppressClickUntil = 0;\n  let resizeTimer;\n  let syncTimer;\n  let syncPaused = false;\n\n  const uid = () => `${Date.now()}-${Math.random().toString(16).slice(2)}`;\n  const clamp = (n, min, max) => Math.max(min, Math.min(max, n));\n  const snapshot = () => JSON.stringify(state);\n\n  function remember() {\n    history.push(snapshot());\n    if (history.length > 30) history.shift();\n    undoBtn.disabled = false;\n  }\n\n  function starterState() {\n    return {\n      notes: [\n        { id: uid(), text: 'What if ideas felt more like play?', color: 'yellow', x: .08, y: .12, tilt: -4, tag: '', doodle: '' },\n        { id: uid(), text: 'messy first.\\nuseful later.', color: 'pink', x: .39, y: .43, tilt: 3, tag: 'process', doodle: '' },\n        { id: uid(), text: 'Build the weird version →', color: 'blue', x: .67, y: .16, tilt: -2, tag: '', doodle: '' }\n      ],\n      arrows: [{ id: uid(), x: .58, y: .53, turn: -18 }],\n      groups: [], saved: [], doodle: '', updatedAt: 0\n    };\n  }\n\n  function normalize(raw) {\n    const next = raw && typeof raw === 'object' ? raw : starterState();\n    next.notes = Array.isArray(next.notes) ? next.notes : [];\n    next.arrows = Array.isArray(next.arrows) ? next.arrows : [];\n    next.groups = Array.isArray(next.groups) ? next.groups : [];\n    next.saved = Array.isArray(next.saved) ? next.saved : [];\n    next.doodle = typeof next.doodle === 'string' ? next.doodle : '';\n    next.updatedAt = Number(next.updatedAt) || 0;\n    next.notes.forEach(note => {\n      note.tag = note.tag || '';\n      note.doodle = note.doodle || '';\n      note.groupId = note.groupId || '';\n    });\n    next.saved.forEach(note => {\n      note.tag = note.tag || '';\n      note.doodle = note.doodle || '';\n    });\n    return next;\n  }\n\n  function loadLocal() {\n    try {\n      const saved = localStorage.getItem(STORAGE_KEY) || localStorage.getItem(LEGACY_KEY);\n      state = normalize(saved ? JSON.parse(saved) : starterState());\n    } catch (_) { state = starterState(); }\n  }\n\n  function save({ touch = true } = {}) {\n    if (touch) state.updatedAt = Date.now();\n    try { localStorage.setItem(STORAGE_KEY, snapshot()); } catch (_) {}\n    if (syncPaused) return;\n    clearTimeout(syncTimer);\n    syncTimer = setTimeout(pushRemote, 450);\n  }\n\n  async function pushRemote() {\n    try {\n      await fetch('/api/state', {\n        method: 'POST', headers: { 'content-type': 'application/json' }, body: snapshot()\n      });\n    } catch (_) {}\n  }\n\n  async function hydrateRemote() {\n    try {\n      const response = await fetch('/api/state', { headers: { accept: 'application/json' } });\n      if (response.status === 204) { pushRemote(); return; }\n      if (!response.ok) return;\n      const payload = await response.json();\n      const remote = normalize(payload.state);\n      if (remote.updatedAt >= state.updatedAt) {\n        syncPaused = true;\n        state = remote;\n        try { localStorage.setItem(STORAGE_KEY, snapshot()); } catch (_) {}\n        render(); restoreDoodle(); syncPaused = false;\n      } else pushRemote();\n    } catch (_) {}\n  }\n\n  function updateUI() {\n    count.textContent = state.notes.length;\n    savedCount.textContent = state.saved.length;\n    empty.hidden = state.notes.length + state.arrows.length > 0;\n    undoBtn.disabled = history.length === 0;\n    selectionCount.textContent = selected.size;\n    archiveSelectedBtn.disabled = selected.size === 0;\n    $('#groupBtn').disabled = selected.size < 2;\n  }\n\n  function render() {\n    layer.replaceChildren();\n    state.arrows.forEach(renderArrow);\n    state.notes.forEach(renderNote);\n    renderSaved();\n    updateSelectionDock();\n    updateUI();\n    requestAnimationFrame(renderGroups);\n  }\n\n  function renderNote(note) {\n    const el = document.createElement('article');\n    el.className = 'sticky';\n    if (selected.has(note.id)) el.classList.add('is-selected');\n    if (note.y > .54) el.classList.add('toolbar-above');\n    el.dataset.id = note.id;\n    el.dataset.kind = 'note';\n    el.dataset.color = note.color;\n    el.style.left = `${note.x * 100}%`;\n    el.style.top = `${note.y * 100}%`;\n    el.style.setProperty('--tilt', `${note.tilt}deg`);\n    el.innerHTML = '<button class=\"delete-note\" type=\"button\" aria-label=\"Delete note\">×</button><canvas class=\"note-ink\" aria-label=\"Note doodle layer\"></canvas><div class=\"sticky-text\" tabindex=\"0\"></div>';\n    const text = el.querySelector('.sticky-text');\n    text.textContent = note.text;\n    if (note.tag) {\n      const tag = document.createElement('span');\n      tag.className = 'note-tag';\n      tag.textContent = `#${note.tag}`;\n      el.appendChild(tag);\n    }\n    if (activeNoteId === note.id && !selectionMode && !canvasMode) el.appendChild(buildNoteToolbar(note, text));\n    const ink = el.querySelector('.note-ink');\n    if (noteDoodleId === note.id) ink.classList.add('is-active');\n    el.addEventListener('pointerdown', startDrag);\n    el.addEventListener('click', event => {\n      if (Date.now() < suppressClickUntil || event.target.closest('button') || event.target.closest('.note-ink') || event.target.contentEditable === 'true') return;\n      if (selectionMode) { toggleSelected(note.id); return; }\n      activeNoteId = activeNoteId === note.id ? null : note.id;\n      noteDoodleId = null;\n      render();\n    });\n    text.addEventListener('dblclick', event => {\n      if (selectionMode || canvasMode) return;\n      event.stopPropagation();\n      beginEditing(text);\n    });\n    text.addEventListener('blur', () => finishEditing(note, text));\n    text.addEventListener('keydown', event => {\n      if (event.key === 'Escape' || ((event.ctrlKey || event.metaKey) && event.key === 'Enter')) text.blur();\n    });\n    el.querySelector('.delete-note').addEventListener('pointerdown', event => event.stopPropagation());\n    el.querySelector('.delete-note').addEventListener('click', event => {\n      event.stopPropagation(); remember();\n      state.notes = state.notes.filter(item => item.id !== note.id);\n      cleanGroups(); activeNoteId = null; render(); save();\n    });\n    layer.appendChild(el);\n    requestAnimationFrame(() => prepareNoteCanvas(note, ink));\n  }\n\n  function buildNoteToolbar(note, text) {\n    const toolbar = document.createElement('div');\n    toolbar.className = 'note-toolbar';\n    toolbar.setAttribute('role', 'toolbar');\n    toolbar.setAttribute('aria-label', 'Note options');\n    toolbar.addEventListener('pointerdown', event => event.stopPropagation());\n    toolbar.addEventListener('click', event => event.stopPropagation());\n    const edit = document.createElement('button');\n    edit.type = 'button'; edit.textContent = 'Edit';\n    edit.addEventListener('click', () => beginEditing(text));\n    toolbar.appendChild(edit);\n    Object.keys(colors).forEach(color => {\n      const button = document.createElement('button');\n      button.type = 'button'; button.className = `toolbar-color ${color}`;\n      button.setAttribute('aria-label', `Change note to ${color}`);\n      button.addEventListener('click', () => { remember(); note.color = color; render(); save(); });\n      toolbar.appendChild(button);\n    });\n    const doodle = document.createElement('button');\n    doodle.type = 'button';\n    doodle.classList.toggle('is-active', noteDoodleId === note.id);\n    doodle.textContent = 'Doodle';\n    doodle.addEventListener('click', () => {\n      noteDoodleId = noteDoodleId === note.id ? null : note.id;\n      render();\n      hint.textContent = noteDoodleId ? 'Draw right on this note. Tap Doodle again when done.' : 'Tap a note for its options.';\n    });\n    toolbar.appendChild(doodle);\n    return toolbar;\n  }\n\n  function beginEditing(text) {\n    noteDoodleId = null;\n    text.contentEditable = 'true'; text.focus();\n    const range = document.createRange();\n    range.selectNodeContents(text); range.collapse(false);\n    const selection = window.getSelection();\n    selection.removeAllRanges(); selection.addRange(range);\n  }\n\n  function finishEditing(note, text) {\n    if (text.contentEditable !== 'true') return;\n    const next = text.textContent.trim() || 'untitled thought';\n    if (next !== note.text) remember();\n    note.text = next; text.textContent = note.text; text.contentEditable = 'false'; save();\n  }\n\n  function prepareNoteCanvas(note, ink) {\n    const ratio = window.devicePixelRatio || 1;\n    ink.width = Math.max(1, Math.round(ink.clientWidth * ratio));\n    ink.height = Math.max(1, Math.round(ink.clientHeight * ratio));\n    const noteCtx = ink.getContext('2d');\n    if (note.doodle) {\n      const image = new Image();\n      image.onload = () => noteCtx.drawImage(image, 0, 0, ink.width, ink.height);\n      image.src = note.doodle;\n    }\n    ink.addEventListener('pointerdown', event => {\n      if (noteDoodleId !== note.id) return;\n      event.stopPropagation(); remember(); ink.setPointerCapture(event.pointerId);\n      const point = localCanvasPoint(ink, event);\n      noteCtx.beginPath(); noteCtx.moveTo(point.x, point.y);\n      noteDrawing = { ink, ctx: noteCtx, note };\n    });\n    ink.addEventListener('pointermove', event => {\n      if (!noteDrawing || noteDrawing.ink !== ink) return;\n      const point = localCanvasPoint(ink, event);\n      noteCtx.lineTo(point.x, point.y);\n      noteCtx.strokeStyle = '#202020'; noteCtx.lineWidth = 2.5 * ratio;\n      noteCtx.lineCap = 'round'; noteCtx.lineJoin = 'round'; noteCtx.stroke();\n    });\n    const finish = event => {\n      if (!noteDrawing || noteDrawing.ink !== ink) return;\n      event.stopPropagation(); note.doodle = ink.toDataURL('image/png'); noteDrawing = null; save();\n    };\n    ink.addEventListener('pointerup', finish);\n    ink.addEventListener('pointercancel', finish);\n  }\n\n  function renderArrow(arrow) {\n    const el = document.createElement('button');\n    el.type = 'button'; el.className = 'arrow-sticker';\n    el.dataset.id = arrow.id; el.dataset.kind = 'arrow';\n    el.setAttribute('aria-label', 'Movable arrow. Double-click to remove.');\n    el.textContent = '↗'; el.style.left = `${arrow.x * 100}%`; el.style.top = `${arrow.y * 100}%`;\n    el.style.setProperty('--turn', `${arrow.turn}deg`);\n    el.addEventListener('pointerdown', startDrag);\n    el.addEventListener('dblclick', () => {\n      remember(); state.arrows = state.arrows.filter(item => item.id !== arrow.id); render(); save();\n    });\n    layer.appendChild(el);\n  }\n\n  function renderGroups() {\n    groupsLayer.replaceChildren();\n    const boardRect = board.getBoundingClientRect();\n    state.groups.forEach(group => {\n      const elements = group.noteIds.map(id => layer.querySelector(`[data-kind=\"note\"][data-id=\"${CSS.escape(id)}\"]`)).filter(Boolean);\n      if (elements.length < 2) return;\n      const rects = elements.map(element => element.getBoundingClientRect());\n      const left = Math.min(...rects.map(rect => rect.left)) - boardRect.left - 12;\n      const top = Math.min(...rects.map(rect => rect.top)) - boardRect.top - 12;\n      const right = Math.max(...rects.map(rect => rect.right)) - boardRect.left + 12;\n      const bottom = Math.max(...rects.map(rect => rect.bottom)) - boardRect.top + 12;\n      const box = document.createElement('div');\n      box.className = 'group-box';\n      box.style.left = `${Math.max(1, left)}px`; box.style.top = `${Math.max(1, top)}px`;\n      box.style.width = `${Math.min(boardRect.width - Math.max(1, left) - 2, right - left)}px`;\n      box.style.height = `${Math.min(boardRect.height - Math.max(1, top) - 2, bottom - top)}px`;\n      box.style.setProperty('--group-color', colors[group.color] || colors.yellow);\n      const label = document.createElement('span');\n      label.className = 'group-label'; label.textContent = group.tag ? `#${group.tag}` : 'idea group';\n      box.appendChild(label); groupsLayer.appendChild(box);\n    });\n  }\n\n  function renderSaved() {\n    savedList.replaceChildren();\n    if (!state.saved.length) {\n      const message = document.createElement('p');\n      message.className = 'saved-empty';\n      message.textContent = 'Nothing tucked away yet. Hit Save, then pick a few notes.';\n      savedList.appendChild(message); return;\n    }\n    [...state.saved].sort((a, b) => (b.savedAt || 0) - (a.savedAt || 0)).forEach((note, index) => {\n      const card = document.createElement('article');\n      card.className = 'saved-card'; card.dataset.color = note.color;\n      card.style.setProperty('--saved-tilt', `${index % 2 ? 1 : -1}deg`);\n      const text = document.createElement('p'); text.textContent = note.text;\n      const footer = document.createElement('footer');\n      const meta = document.createElement('small');\n      meta.textContent = note.tag ? `#${note.tag}` : formatSavedDate(note.savedAt);\n      const actions = document.createElement('div');\n      const restore = document.createElement('button');\n      restore.type = 'button'; restore.textContent = 'Restore ↗';\n      restore.addEventListener('click', () => restoreSaved(note.id));\n      const discard = document.createElement('button');\n      discard.type = 'button'; discard.className = 'discard-saved';\n      discard.setAttribute('aria-label', 'Delete saved note'); discard.textContent = '×';\n      discard.addEventListener('click', () => discardSaved(note.id));\n      actions.append(restore, discard); footer.append(meta, actions); card.append(text, footer); savedList.appendChild(card);\n    });\n  }\n\n  function formatSavedDate(timestamp) {\n    if (!timestamp) return 'saved note';\n    return new Intl.DateTimeFormat(undefined, { month: 'short', day: 'numeric' }).format(new Date(timestamp));\n  }\n\n  function startDrag(event) {\n    if (canvasMode || selectionMode || noteDoodleId || event.target.closest('button') || event.target.contentEditable === 'true' || event.target.closest('.note-ink')) return;\n    const el = event.currentTarget;\n    const item = state[el.dataset.kind === 'note' ? 'notes' : 'arrows'].find(entry => entry.id === el.dataset.id);\n    if (!item) return;\n    event.preventDefault(); remember();\n    const rect = el.getBoundingClientRect();\n    drag = { el, item, dx: event.clientX - rect.left, dy: event.clientY - rect.top, moved: false, startX: event.clientX, startY: event.clientY };\n    el.classList.add('is-dragging'); el.setPointerCapture(event.pointerId);\n    el.addEventListener('pointermove', moveDrag);\n    el.addEventListener('pointerup', endDrag, { once: true });\n    el.addEventListener('pointercancel', endDrag, { once: true });\n  }\n\n  function moveDrag(event) {\n    if (!drag) return;\n    if (Math.hypot(event.clientX - drag.startX, event.clientY - drag.startY) > 4) drag.moved = true;\n    const bounds = board.getBoundingClientRect();\n    const x = clamp(event.clientX - bounds.left - drag.dx, 0, bounds.width - drag.el.offsetWidth);\n    const y = clamp(event.clientY - bounds.top - drag.dy, 0, bounds.height - drag.el.offsetHeight);\n    drag.item.x = x / bounds.width; drag.item.y = y / bounds.height;\n    drag.el.style.left = `${drag.item.x * 100}%`; drag.el.style.top = `${drag.item.y * 100}%`;\n    renderGroups();\n  }\n\n  function endDrag(event) {\n    if (!drag) return;\n    if (drag.moved) suppressClickUntil = Date.now() + 300;\n    drag.el.classList.remove('is-dragging'); drag.el.removeEventListener('pointermove', moveDrag);\n    try { drag.el.releasePointerCapture(event.pointerId); } catch (_) {}\n    drag = null; save();\n  }\n\n  function addNote(text) {\n    remember();\n    const offset = state.notes.length % 6;\n    state.notes.push({\n      id: uid(), text, color: selectedColor,\n      x: clamp(.12 + offset * .105, .02, .72), y: clamp(.11 + (offset % 3) * .16, .03, .67),\n      tilt: [-4, 2, -1, 4, -3, 1][offset], tag: '', doodle: '', groupId: ''\n    });\n    render(); save();\n  }\n\n  function toggleSelected(id) {\n    if (selected.has(id)) selected.delete(id); else selected.add(id);\n    activeNoteId = null; render();\n  }\n\n  function setSelectionMode(mode) {\n    selectionMode = selectionMode === mode ? null : mode;\n    selected.clear(); activeNoteId = null; noteDoodleId = null; setCanvasMode(null);\n    saveBtn.setAttribute('aria-pressed', String(selectionMode === 'save'));\n    selectBtn.setAttribute('aria-pressed', String(selectionMode === 'select'));\n    hint.textContent = selectionMode === 'save' ? 'Tap the notes you want to tuck away.' : selectionMode === 'select' ? 'Tap notes, then group, tag, or recolor them.' : 'Tap a note for options. Drag to move it.';\n    render();\n  }\n\n  function updateSelectionDock() {\n    selectionDock.hidden = !selectionMode;\n    if (!selectionMode) return;\n    const saving = selectionMode === 'save';\n    selectionTitle.textContent = saving ? 'Pick notes to save' : 'Pick notes to change';\n    batchTools.hidden = saving; archiveSelectedBtn.hidden = !saving;\n  }\n\n  function applyToSelected(action) {\n    if (!selected.size) return;\n    remember(); state.notes.filter(note => selected.has(note.id)).forEach(action); render(); save();\n  }\n\n  function groupSelected() {\n    if (selected.size < 2) return;\n    remember();\n    const ids = [...selected];\n    const notes = state.notes.filter(note => selected.has(note.id));\n    state.groups.forEach(group => { group.noteIds = group.noteIds.filter(id => !selected.has(id)); });\n    cleanGroups();\n    const id = uid();\n    const tag = tagInput.value.trim().replace(/^#/, '') || `group ${state.groups.length + 1}`;\n    notes.forEach(note => { note.groupId = id; if (!note.tag && tagInput.value.trim()) note.tag = tag; });\n    state.groups.push({ id, noteIds: ids, tag, color: notes[0]?.color || 'yellow' });\n    selected.clear(); tagInput.value = ''; render(); save();\n    hint.textContent = 'Grouped! The dashed box keeps these thoughts connected.';\n  }\n\n  function cleanGroups() {\n    const activeIds = new Set(state.notes.map(note => note.id));\n    state.groups.forEach(group => { group.noteIds = group.noteIds.filter(id => activeIds.has(id)); });\n    state.groups = state.groups.filter(group => group.noteIds.length > 1);\n  }\n\n  function archiveSelected() {\n    if (!selected.size) return;\n    remember();\n    const now = Date.now();\n    const moving = state.notes.filter(note => selected.has(note.id)).map(note => ({ ...note, savedAt: now, groupId: '' }));\n    state.saved.push(...moving);\n    state.notes = state.notes.filter(note => !selected.has(note.id));\n    cleanGroups();\n    const moved = moving.length;\n    setSelectionMode(null); render(); save(); openSaved();\n    hint.textContent = `${moved} note${moved === 1 ? '' : 's'} saved for later.`;\n  }\n\n  function restoreSaved(id) {\n    const note = state.saved.find(item => item.id === id);\n    if (!note) return;\n    remember();\n    const offset = state.notes.length % 5;\n    state.notes.push({ ...note, x: .08 + offset * .12, y: .1 + (offset % 3) * .16, savedAt: undefined, groupId: '' });\n    state.saved = state.saved.filter(item => item.id !== id);\n    render(); save(); hint.textContent = 'That thought is back on the board.';\n  }\n\n  function discardSaved(id) {\n    remember(); state.saved = state.saved.filter(item => item.id !== id); render(); save();\n  }\n\n  function openSaved() {\n    savedDrawer.hidden = false; savedBtn.setAttribute('aria-expanded', 'true'); renderSaved();\n  }\n  function closeSaved() {\n    savedDrawer.hidden = true; savedBtn.setAttribute('aria-expanded', 'false');\n  }\n\n  form.addEventListener('submit', event => {\n    event.preventDefault();\n    const text = input.value.trim();\n    if (!text) return;\n    addNote(text); input.value = ''; input.focus();\n  });\n\n  document.querySelectorAll('.swatch').forEach(button => {\n    button.addEventListener('click', () => {\n      selectedColor = button.dataset.color;\n      document.querySelectorAll('.swatch').forEach(swatch => swatch.classList.toggle('is-selected', swatch === button));\n      input.style.background = colors[selectedColor]; input.focus();\n    });\n  });\n\n  document.querySelectorAll('[data-batch-color]').forEach(button => {\n    button.addEventListener('click', () => applyToSelected(note => { note.color = button.dataset.batchColor; }));\n  });\n  $('#tagBtn').addEventListener('click', () => {\n    const tag = tagInput.value.trim().replace(/^#/, '');\n    if (!tag) return;\n    applyToSelected(note => { note.tag = tag; }); tagInput.value = '';\n  });\n  tagInput.addEventListener('keydown', event => { if (event.key === 'Enter') { event.preventDefault(); $('#tagBtn').click(); } });\n  $('#groupBtn').addEventListener('click', groupSelected);\n  archiveSelectedBtn.addEventListener('click', archiveSelected);\n  $('#cancelSelectionBtn').addEventListener('click', () => setSelectionMode(null));\n  saveBtn.addEventListener('click', () => setSelectionMode('save'));\n  selectBtn.addEventListener('click', () => setSelectionMode('select'));\n  savedBtn.addEventListener('click', () => savedDrawer.hidden ? openSaved() : closeSaved());\n  $('#closeSavedBtn').addEventListener('click', closeSaved);\n\n  arrowBtn.addEventListener('click', () => {\n    remember();\n    const n = state.arrows.length;\n    state.arrows.push({ id: uid(), x: .34 + (n % 4) * .11, y: .3 + (n % 3) * .13, turn: [-24, 12, -8, 27][n % 4] });\n    render(); save(); hint.textContent = 'Arrow added—drag it where the connection clicks.';\n  });\n\n  tidyBtn.addEventListener('click', () => {\n    if (!state.notes.length) return;\n    remember();\n    const cols = board.clientWidth < 520 ? 2 : board.clientWidth < 850 ? 3 : 4;\n    state.notes.forEach((note, index) => {\n      note.x = .035 + (index % cols) * (.91 / cols);\n      note.y = .05 + Math.floor(index / cols) * .34;\n      note.tilt = [-2, 1, -1, 2][index % 4];\n    });\n    render(); save(); hint.textContent = 'A little order. Still enough chaos.';\n  });\n\n  undoBtn.addEventListener('click', () => {\n    if (!history.length) return;\n    state = normalize(JSON.parse(history.pop()));\n    selected.clear(); activeNoteId = null; noteDoodleId = null;\n    render(); restoreDoodle(); save();\n  });\n\n  clearBtn.addEventListener('click', () => {\n    if (!clearArmed) {\n      clearArmed = true;\n      clearBtn.innerHTML = '<span class=\"tool-icon\" aria-hidden=\"true\">!</span>Sure?';\n      hint.textContent = 'Click “Sure?” once more to clear the active board. Saved notes stay safe.';\n      setTimeout(() => {\n        clearArmed = false;\n        clearBtn.innerHTML = '<span class=\"tool-icon\" aria-hidden=\"true\">×</span>Clear';\n      }, 3000);\n      return;\n    }\n    remember();\n    state.notes = []; state.arrows = []; state.groups = []; state.doodle = '';\n    ctx.clearRect(0, 0, canvas.width, canvas.height);\n    clearArmed = false; clearBtn.innerHTML = '<span class=\"tool-icon\" aria-hidden=\"true\">×</span>Clear';\n    render(); save();\n  });\n\n  doodleBtn.addEventListener('click', () => setCanvasMode(canvasMode === 'draw' ? null : 'draw'));\n  eraserBtn.addEventListener('click', () => setCanvasMode(canvasMode === 'erase' ? null : 'erase'));\n\n  function setCanvasMode(mode) {\n    canvasMode = mode;\n    if (mode) { selectionMode = null; selected.clear(); activeNoteId = null; noteDoodleId = null; }\n    canvas.classList.toggle('is-active', Boolean(mode));\n    canvas.classList.toggle('is-erasing', mode === 'erase');\n    doodleBtn.setAttribute('aria-pressed', String(mode === 'draw'));\n    eraserBtn.setAttribute('aria-pressed', String(mode === 'erase'));\n    saveBtn.setAttribute('aria-pressed', 'false'); selectBtn.setAttribute('aria-pressed', 'false');\n    hint.textContent = mode === 'draw' ? 'Doodle mode: draw anywhere. Tap Doodle again when done.' : mode === 'erase' ? 'Eraser mode: scrub over doodles to remove them.' : 'Tap a note for options. Drag to move it.';\n    updateSelectionDock();\n  }\n\n  function localCanvasPoint(target, event) {\n    const rect = target.getBoundingClientRect();\n    return { x: (event.clientX - rect.left) * target.width / rect.width, y: (event.clientY - rect.top) * target.height / rect.height };\n  }\n\n  canvas.addEventListener('pointerdown', event => {\n    if (!canvasMode) return;\n    remember(); drawing = true; canvas.setPointerCapture(event.pointerId);\n    const point = localCanvasPoint(canvas, event);\n    ctx.beginPath(); ctx.moveTo(point.x, point.y);\n  });\n  canvas.addEventListener('pointermove', event => {\n    if (!drawing) return;\n    const point = localCanvasPoint(canvas, event);\n    ctx.lineTo(point.x, point.y);\n    ctx.globalCompositeOperation = canvasMode === 'erase' ? 'destination-out' : 'source-over';\n    ctx.strokeStyle = '#202020';\n    ctx.lineWidth = (canvasMode === 'erase' ? 24 : 3) * (window.devicePixelRatio || 1);\n    ctx.lineCap = 'round'; ctx.lineJoin = 'round'; ctx.stroke();\n  });\n  const finishDrawing = () => {\n    if (!drawing) return;\n    drawing = false; ctx.globalCompositeOperation = 'source-over';\n    state.doodle = canvas.toDataURL('image/png'); save();\n  };\n  canvas.addEventListener('pointerup', finishDrawing);\n  canvas.addEventListener('pointercancel', finishDrawing);\n\n  function restoreDoodle() {\n    ctx.clearRect(0, 0, canvas.width, canvas.height);\n    if (!state.doodle) return;\n    const image = new Image();\n    image.onload = () => ctx.drawImage(image, 0, 0, canvas.width, canvas.height);\n    image.src = state.doodle;\n  }\n\n  function sizeCanvas() {\n    const previous = state.doodle || (canvas.width ? canvas.toDataURL('image/png') : '');\n    const rect = board.getBoundingClientRect();\n    canvas.width = Math.max(1, Math.round(rect.width * (window.devicePixelRatio || 1)));\n    canvas.height = Math.max(1, Math.round(rect.height * (window.devicePixelRatio || 1)));\n    state.doodle = previous; restoreDoodle(); requestAnimationFrame(renderGroups);\n  }\n\n  window.addEventListener('resize', () => {\n    clearTimeout(resizeTimer); resizeTimer = setTimeout(() => { sizeCanvas(); render(); }, 120);\n  });\n  document.addEventListener('keydown', event => {\n    if (event.key !== 'Escape') return;\n    if (!savedDrawer.hidden) closeSaved();\n    else if (selectionMode) setSelectionMode(null);\n    else if (canvasMode) setCanvasMode(null);\n    else if (activeNoteId) { activeNoteId = null; noteDoodleId = null; render(); }\n  });\n\n  loadLocal(); render(); requestAnimationFrame(sizeCanvas); hydrateRemote();\n})();\n","type":"text/javascript; charset=utf-8"}};

const jsonHeaders = {
  'content-type': 'application/json; charset=utf-8',
  'cache-control': 'no-store',
  'x-content-type-options': 'nosniff'
};

async function handleState(request, env) {
  if (!env.DB) return new Response(JSON.stringify({ error: 'Storage unavailable' }), { status: 503, headers: jsonHeaders });
  const userKey = request.headers.get('oai-authenticated-user-email') || 'owner';

  if (request.method === 'GET') {
    const row = await env.DB.prepare('SELECT payload, updated_at FROM app_state WHERE user_key = ?')
      .bind(userKey)
      .first();
    if (!row) return new Response(null, { status: 204, headers: { 'cache-control': 'no-store' } });
    try {
      return new Response(JSON.stringify({ state: JSON.parse(row.payload), updatedAt: row.updated_at }), { headers: jsonHeaders });
    } catch {
      return new Response(JSON.stringify({ error: 'Saved state is unreadable' }), { status: 500, headers: jsonHeaders });
    }
  }

  if (request.method === 'POST') {
    const text = await request.text();
    if (text.length > 3000000) return new Response(JSON.stringify({ error: 'Board is too large to save' }), { status: 413, headers: jsonHeaders });
    let payload;
    try {
      payload = JSON.parse(text);
      if (!payload || !Array.isArray(payload.notes) || !Array.isArray(payload.saved)) throw new Error('invalid');
    } catch {
      return new Response(JSON.stringify({ error: 'Invalid board state' }), { status: 400, headers: jsonHeaders });
    }
    const updatedAt = new Date().toISOString();
    await env.DB.prepare(
      'INSERT INTO app_state (user_key, payload, updated_at) VALUES (?, ?, ?) ON CONFLICT(user_key) DO UPDATE SET payload = excluded.payload, updated_at = excluded.updated_at'
    ).bind(userKey, JSON.stringify(payload), updatedAt).run();
    return new Response(JSON.stringify({ ok: true, updatedAt }), { headers: jsonHeaders });
  }

  return new Response(JSON.stringify({ error: 'Method not allowed' }), { status: 405, headers: { ...jsonHeaders, allow: 'GET, POST' } });
}

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    if (url.pathname === '/api/state') return handleState(request, env);
    const asset = routes[url.pathname];
    if (!asset) {
      return new Response('Not found', { status: 404 });
    }
    return new Response(request.method === 'HEAD' ? null : asset.body, {
      status: 200,
      headers: {
        'content-type': asset.type,
        'cache-control': 'no-cache, must-revalidate',
        'x-content-type-options': 'nosniff'
      }
    });
  }
};
